function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

delay(1000).then(() => console.log("Minela sekunda"));

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

Promise.all([
  delay(300).then(() => "A"),
  delay(100).then(() => "B"),
  delay(200).then(() => "C"),
]).then((wyniki) => console.log(wyniki)); // ["A", "B", "C"] - zachowana kolejnosc

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

Promise.race([
  delay(300).then(() => "A"),
  delay(100).then(() => "B"),
  delay(200).then(() => "C"),
]).then((wygrany) => console.log("Wygral:", wygrany)); // "Wygral: B" (najszybszy)

const fetchUser = (id) => new Promise((resolve, reject) => {
  setTimeout(() => {
    if (id > 0) resolve({ id, name: `User ${id}` });
    else reject(new Error(`Nieprawidlowe id: ${id}`));
  }, 100);
});

Promise.allSettled([fetchUser(1), fetchUser(-1)]).then((wyniki) => {
  wyniki.forEach((w) => console.log(w.status));
});
// "fulfilled"
// "rejected"

// Promise.all() 'pada' (rejectuje) NATYCHMIAST, gdy KTORYKOLWIEK z
// przekazanych Promise zostanie odrzucony - nawet jesli pozostale wciaz
// trwaja, caly Promise.all() natychmiast konczy sie bledem. Uzywaj go,
// gdy WSZYSTKIE wyniki sa wymagane, a brak jednego 'psuje' calosc
// (np. potrzebujesz wszystkich danych, zeby cokolwiek pokazac).
//
// Promise.allSettled() ZAWSZE czeka na WSZYSTKIE, niezaleznie od tego,
// czy poszczegolne Promise sie udaly, czy nie - zwraca tablice ze
// statusem KAZDEGO z osobna. Uzywaj go, gdy chcesz 'zobaczyc wszystkie
// wyniki naraz', nawet jesli niektore z nich zakoncza sie bledem
// (np. proba pobrania danych z kilku niezaleznych zrodel, gdzie awaria
// jednego nie powinna blokowac wynikow pozostalych).
